{
  "application": "report-generation",
  "case_id": "case-gold-price-dynamics-analysis-en",
  "language": "en",
  "report": {
    "type": "trend-analysis",
    "audience": "analyst",
    "tone": "analytical, detailed, data-forward"
  },
  "brief": {
    "title": "Gold Price Dynamics: A Comprehensive Trend and Volatility Analysis (2000–2025)",
    "one_liner": "An in-depth analysis of gold price behavior over two decades, covering price trends, volatility regimes, seasonal patterns, and momentum dynamics.",
    "goal": "Equip financial analysts with a thorough understanding of gold's historical price structure, volatility clustering, seasonal tendencies, and liquidity patterns to inform macro-asset allocation and risk management decisions."
  },
  "required_sections": [
    {
      "section_id": "market-overview",
      "title": "Market Overview & Long-Term Price Trend",
      "objective": "Summarize the overall trajectory of gold prices from 2000 to the present, highlighting major bull and bear phases, all-time highs, and key inflection points."
    },
    {
      "section_id": "volatility-analysis",
      "title": "Volatility Analysis & Regime Detection",
      "objective": "Analyze rolling volatility measures (e.g., rolling standard deviation of returns), identify periods of volatility clustering, and characterize distinct market regimes (low-vol, high-vol, crisis)."
    },
    {
      "section_id": "seasonal-patterns",
      "title": "Seasonal & Calendar-Based Patterns",
      "objective": "Examine whether gold exhibits recurring monthly or day-of-week patterns in returns and volume, and quantify the strength of any seasonal effects."
    },
    {
      "section_id": "return-distribution",
      "title": "Return Distribution & Tail Risk",
      "objective": "Profile the statistical distribution of daily returns including skewness, kurtosis, and tail behavior to assess the risk characteristics of gold as an asset."
    },
    {
      "section_id": "momentum-liquidity",
      "title": "Momentum Dynamics & Liquidity Behavior",
      "objective": "Evaluate short- and medium-term momentum signals (e.g., moving average crossovers, rate of change) and analyze how trading volume relates to price movements and trend strength."
    },
    {
      "section_id": "key-takeaways",
      "title": "Key Takeaways & Forward-Looking Considerations",
      "objective": "Synthesize findings into actionable insights for portfolio construction and risk management, noting current regime context and potential scenarios."
    }
  ],
  "kpis": [
    {
      "name": "Annualized Return",
      "description": "Compound annual growth rate (CAGR) of gold's closing price over the full dataset period."
    },
    {
      "name": "Annualized Volatility",
      "description": "Standard deviation of daily log returns, annualized (×√252), as a measure of overall risk."
    },
    {
      "name": "Maximum Drawdown",
      "description": "Largest peak-to-trough decline in closing price, indicating worst-case loss scenario."
    },
    {
      "name": "Average Daily Volume",
      "description": "Mean daily trading volume across the dataset, serving as a baseline liquidity indicator."
    },
    {
      "name": "Sharpe-Like Ratio",
      "description": "Annualized return divided by annualized volatility (assuming zero risk-free rate) as a simple risk-adjusted performance metric."
    }
  ],
  "analysis_dimensions": [
    "Date",
    "Close",
    "Volume",
    "High",
    "Low"
  ]
}

